Section RW.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x1 x5 x6 x7 x8 x9 x10 x11 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word).
  Variables (m : fmem) (HW nbS scale : Z) (ws : list Z) (jk : list byte).
  Variable POST : machine_state -> Prop.
  Hypothesis HNS : 1 <= nbS <= 256.
  Hypothesis LWS : zlen ws = nbS.
  Hypothesis WSR : Forall (fun w => 0 <= w < 256) ws.
  Hypothesis HSC : 1 <= scale <= 11.
  Hypothesis LJK : zlen jk = 256 - nbS.
  Hypothesis HHW : 0 < HW /\ HW + 256 <= 2^47.

  Notation ARRK m1 k := (u8arr psegs m1 HW (map (Z_to_bv 8) (map (rsw1 scale) (firstn (Z.to_nat k) ws) ++ skipn (Z.to_nat k) ws) ++ jk)).

  Lemma rw_loop : forall f k m1 (x15 x16 : word),
    Z.of_nat f = nbS - k -> 0 <= k < nbS -> ARRK m1 k ->
    munch [(HW, HW + 256)] m m1 -> wmono psegs m m1 -> mem_inv psegs m1 ->
    (forall m2 (y15 y16 : word), ARRK m2 nbS -> munch [(HW, HW + 256)] m m2 -> wmono psegs m m2 -> mem_inv psegs m2 ->
       evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 x8 x9 x10 x11 (Z_to_bv 64 scale) (Z_to_bv 64 (HW + nbS))
                               (Z_to_bv 64 (HW + nbS)) y15 y16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                          F (Z_to_bv 64 0x134f8) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 x8 x9 x10 x11 (Z_to_bv 64 scale) (Z_to_bv 64 (HW + nbS))
                            (Z_to_bv 64 (HW + k)) x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
