Section SH.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x1 x5 x6 x7 x9 x11 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word).
  Variables (m : fmem) (WK scale : Z).
  Notation NS4 := (Z_to_bv 64 (18446744073709551616 - 4 * scale)).
  Variable POST : machine_state -> Prop.
  Hypothesis HSC : 1 <= scale <= 11.
  Hypothesis HWK : 0 < WK /\ WK + 52 <= 2^47.

  Lemma sh_loop : forall f s rank m1 r (x15 : word),
    shift_rank f s scale rank = Ok r -> Z.of_nat f = s - scale -> scale < s <= 12 -> zlen rank = 13 ->
    Forall (fun v => 0 <= v <= 256) rank ->
    u32arr psegs m1 WK (map (Z_to_bv 64) rank) ->
    munch [(WK, WK + 52)] m m1 -> wmono psegs m m1 -> mem_inv psegs m1 ->
    (forall m2 (y10 y14 y15 : word), u32arr psegs m2 WK (map (Z_to_bv 64) r) -> zlen r = 13 ->
       Forall (fun v => 0 <= v <= 256) r ->
       munch [(WK, WK + 52)] m m2 -> wmono psegs m m2 -> mem_inv psegs m2 ->
       evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 (Z_to_bv 64 WK) x9 y10 x11 (Z_to_bv 64 scale) NS4 y14 y15 x16 x17 x18
                               x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                          F (Z_to_bv 64 0x1352c) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 (Z_to_bv 64 WK) x9 (Z_to_bv 64 (WK + 4 * s)) x11 (Z_to_bv 64 scale) NS4
                            (Z_to_bv 64 s) x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                       F (Z_to_bv 64 0x13514) fc None m1 (seg_rom psegs)).
Proof.
